pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // 1. keep the domain wide: any address is an admissible new owner,
        //    but the caller (the current owner, address(this)) must differ so
        //    the spurious `owner = msg.sender` write is observable.
        vm.assume(newOwner != address(this));

        // 2. drive c through `transferOwnership`: the current owner hands
        //    ownership to the fuzzed newOwner, and the new owner then performs
        //    an owner-only action (`owned`).
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.owned();

        // 3. general rule: after an authorized transfer, ownership is exactly
        //    `newOwner` and owner-only actions by the new owner do not change it.
        assertTrue(c.owner() == newOwner);
    }
}

