pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Establish ownership: contract starts with owner == address(0), so the
        // zero address legitimately performs the first authorized transfer to
        // `caller`. Both versions behave identically here.
        vm.prank(address(0));
        c.transferOwnership(caller);

        // Admissible domain: a genuinely authorized, changing transfer.
        vm.assume(caller != address(0));
        vm.assume(newOwner != caller);

        // The current owner transfers ownership to a fuzzed new owner.
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // General rule: after an authorized transferOwnership(newOwner), the
        // owner is exactly newOwner. The buggy modifier overwrites owner with
        // msg.sender (the caller), which differs from newOwner for the
        // admissible inputs above.
        assertTrue(c.owner() == newOwner);
    }
}

