pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        // set a concrete (nonzero) owner so the ownership state is meaningful
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // drive c through owned from an arbitrary fuzzed actor
        vm.prank(caller);
        try c.owned() {
            // if owned() succeeded, the caller was the owner; ownership must be preserved
            assertTrue(c.owner() == newOwner, "owned() must not change ownership");
        } catch {
            // if it reverted, the caller was not the owner; ownership must be untouched
            assertTrue(c.owner() == newOwner, "reverting owned() must not change ownership");
        }
    }
}

